-- ETL, data maintenance and admin queries
INSERT INTO dim_customer (customer_id, name, region) SELECT c.id, c.name, r.name FROM staging_customers c JOIN regions r ON r.id = c.region_id ON DUPLICATE KEY UPDATE name = VALUES(name), region = VALUES(region);
INSERT INTO daily_stats (day, orders, revenue) SELECT DATE(created_at), COUNT(*), SUM(total) FROM orders WHERE created_at >= CURDATE() - INTERVAL 1 DAY GROUP BY DATE(created_at) ON DUPLICATE KEY UPDATE orders = VALUES(orders), revenue = VALUES(revenue);
UPDATE target t INNER JOIN source s ON s.id = t.id SET t.a = s.a, t.b = s.b WHERE t.a <> s.a OR t.b <> s.b;
UPDATE users u SET u.order_count = (SELECT COUNT(*) FROM orders o WHERE o.customer_id = u.id);
UPDATE orders SET total = total * 1.1 WHERE status = 'new' ORDER BY id LIMIT 1000;
UPDATE t SET a = b, b = a;
UPDATE IGNORE t SET id = id + 1000;
UPDATE LOW_PRIORITY t SET x = 1;
DELETE LOW_PRIORITY QUICK IGNORE FROM logs WHERE ts < NOW() - INTERVAL 90 DAY;
DELETE FROM t1 USING t1 LEFT JOIN t2 ON t1.id = t2.id WHERE t2.id IS NULL;
INSERT LOW_PRIORITY INTO t (a) VALUES (1);
REPLACE INTO t (id, v) SELECT id, v FROM staging;
REPLACE t SET id = 1, v = 'x';
SELECT table_schema, table_name, ROUND((data_length + index_length) / 1024 / 1024, 2) AS size_mb FROM information_schema.tables WHERE table_schema = DATABASE() ORDER BY size_mb DESC LIMIT 20;
SELECT user, host FROM mysql.user;
SELECT COLUMN_NAME, DATA_TYPE, IS_NULLABLE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'app' AND TABLE_NAME = 'users' ORDER BY ORDINAL_POSITION;
SELECT * FROM performance_schema.events_statements_summary_by_digest ORDER BY SUM_TIMER_WAIT DESC LIMIT 10;
SELECT * FROM sys.schema_unused_indexes;
SELECT id, user, host, db, command, time, state, info FROM information_schema.processlist WHERE command <> 'Sleep' ORDER BY time DESC;
GRANT SELECT, INSERT, UPDATE ON app.* TO 'app'@'%';
GRANT ALL PRIVILEGES ON *.* TO 'admin'@'localhost' WITH GRANT OPTION;
REVOKE INSERT ON app.* FROM 'app'@'%';
CREATE USER 'app'@'%' IDENTIFIED BY 'secret';
CREATE USER IF NOT EXISTS 'ro'@'10.0.0.%' IDENTIFIED BY 'x';
DROP USER IF EXISTS 'old'@'%';
ALTER USER 'app'@'%' IDENTIFIED BY 'new';
CREATE ROLE 'reporting';
CALL refresh_stats(2024, 'full');
CALL sp_noargs();
PREPARE stmt FROM 'SELECT * FROM users WHERE id = ?';
EXECUTE stmt USING @id;
DEALLOCATE PREPARE stmt;
SELECT * FROM users WHERE id = ? AND status = ?;
INSERT INTO t (a, b) VALUES (?, ?), (?, ?);
CREATE TRIGGER trg_bi BEFORE INSERT ON users FOR EACH ROW SET NEW.created_at = NOW();
CREATE EVENT ev_purge ON SCHEDULE EVERY 1 DAY DO DELETE FROM sessions WHERE expires < NOW();
CREATE FUNCTION add1(x INT) RETURNS INT DETERMINISTIC RETURN x + 1;
